use pyac_vliw_core::word_code::{decode, encode};

/// Ground truth: every spelling in the vocabulary, encoded by the reference
/// JavaScript codec (`program/library/vliw/word_code.mjs`), which in turn
/// mirrors the C implementation in `~/pyac/lwonprom/program/encoding.c`.
///
/// The corpus is generated by:
///   node -e '...' > /tmp/pyac_words.json
/// and this test skips when it is absent, so the repository stays buildable
/// without it. Format: `<spelling>\t<hex identity>` per line.
fn corpus() -> Option<Vec<(String, u16)>> {
    let text = std::fs::read_to_string("/tmp/pyac_words.tsv").ok()?;
    let mut rows = Vec::new();
    for line in text.lines() {
        let (word, hnuc) = line.split_once('\t')?;
        let value = u16::from_str_radix(hnuc.trim(), 16).ok()?;
        rows.push((word.to_string(), value));
    }
    Some(rows)
}

#[test]
fn every_vocabulary_spelling_encodes_to_the_reference_identity() {
    let Some(corpus) = corpus() else {
        eprintln!("skipping: /tmp/pyac_words.json is absent");
        return;
    };
    assert!(corpus.len() > 7_000, "corpus should cover the vocabulary");
    let mut failures = Vec::new();
    for (word, expected) in &corpus {
        match encode(word) {
            Ok(actual) if actual == *expected => {}
            Ok(actual) => failures.push(format!(
                "{word}: rust 0x{actual:04x} != ref 0x{expected:04x}"
            )),
            Err(error) => failures.push(format!("{word}: rust rejected {error:?}")),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} spellings disagree: {:?}",
        failures.len(),
        corpus.len(),
        &failures[..failures.len().min(10)]
    );
}

#[test]
fn every_vocabulary_identity_decodes_to_its_own_spelling() {
    let Some(corpus) = corpus() else {
        eprintln!("skipping: /tmp/pyac_words.json is absent");
        return;
    };
    let mut failures = Vec::new();
    for (word, identity) in &corpus {
        let mut buffer = [0u8; 8];
        match decode(*identity, &mut buffer) {
            Ok(length) => {
                let decoded = std::str::from_utf8(&buffer[..length]).unwrap_or("<invalid>");
                if decoded != word.as_str() {
                    failures.push(format!("0x{identity:04x}: {decoded} != {word}"));
                }
            }
            Err(error) => failures.push(format!("0x{identity:04x} ({word}): {error:?}")),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} identities disagree: {:?}",
        failures.len(),
        corpus.len(),
        &failures[..failures.len().min(10)]
    );
}

#[test]
fn encoding_round_trips_through_decoding() {
    for word in ["sa", "na", "pyan", "li", "gi", "hnan", "hnit", "prah", "tu"] {
        let identity = encode(word).expect("encodes");
        let mut buffer = [0u8; 8];
        let length = decode(identity, &mut buffer).expect("decodes");
        assert_eq!(
            std::str::from_utf8(&buffer[..length]).unwrap(),
            word,
            "{word} must round-trip"
        );
    }
}

#[test]
fn the_words_of_sana_pyanli_carry_the_expected_identities() {
    // The pyac base form: sa na pyan li, no type word.
    assert_eq!(encode("sa").unwrap(), 0x253e);
    assert_eq!(encode("na").unwrap(), 0x24de);
    assert_eq!(encode("pyan").unwrap(), 0x6904);
    assert_eq!(encode("li").unwrap(), 0x217e);
}

#[test]
fn identity_classification_agrees_with_spelling_classification() {
    let Some(corpus) = corpus() else {
        eprintln!("skipping: /tmp/pyac_words.tsv is absent");
        return;
    };
    let mut failures = Vec::new();
    for (word, identity) in &corpus {
        let by_spelling = pyac_vliw_core::word_code::classify(word.as_bytes()).ok();
        let by_identity = pyac_vliw_core::word_code::classify_identity(*identity);
        if by_spelling != by_identity {
            failures.push(format!(
                "{word} 0x{identity:04x}: {by_spelling:?} != {by_identity:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} disagree: {:?}",
        failures.len(),
        corpus.len(),
        &failures[..failures.len().min(10)]
    );
}

#[test]
fn names_are_root_words_and_grammar_words_are_not() {
    use pyac_vliw_core::word_code::{WordClass, classify_identity};
    let is_root = |value: u16| {
        matches!(
            classify_identity(value),
            Some(WordClass::LongRoot) | Some(WordClass::ShortRoot)
        )
    };
    // Roots: valid name payloads.
    for root in [0x6930u16, 0x4930, 0x2818, 0x68b1, 0xaa90] {
        assert!(is_root(root), "0x{root:04x} should be a root");
    }
    // Grammar words: never a name payload.
    for grammar in [0x253eu16, 0x24de, 0x225e, 0x327e] {
        assert!(!is_root(grammar), "0x{grammar:04x} is a grammar word");
    }
}
